  "source_findings": [
    {
      "area": "Conversion and error identity",
      "finding": "Read exact upstream rusqlite0.40.1 Row::get, Row::get_ref, FromSql<String> and ValueRef::as_str. Old String conversion is UTF8 as_str then ToString. Candidate skips only ToString on successful TEXT; invalid UTF8 uses Error::Utf8Error(0,error), other SQLite types use InvalidColumnType(0,column_name,data_type). get_ref applies the same column-index validation first. column_name(0) remains valid after successful get_ref(0). Errors are still mapped by unchanged db_error. No lossy conversion or NULL-as-empty acceptance."
    },
    {
      "area": "Borrow lifetime and two cursors",
      "finding": "Rows::next returns a row tied to its mutable borrow. next_row returns a str with that same borrow lifetime. next_pair has independent A/B lifetimes and steps A then B; stepping the independent B statement does not advance/reset A. Both references are consumed inside one loop iteration and never stored in the report; owned JSON examples and digests are produced before advancing either cursor. No unsafe introduced."
    },
    {
      "area": "Error order",
      "finding": "next_pair performs A sqlite3_step and A text conversion before B sqlite3_step/conversion, preserving both early failures and EOF behavior. The comparison, bounded example decoding, A digest then B digest follow in their old order. Holding A text while B advances changes allocation retention but neither source snapshot nor SQL statement ordering."
    },
    {
      "area": "Duplicate and equality semantics",
      "finding": "Sorted SQL including BINARY collation, primary key duplicate ordinal, append_digest position and Value equality fallback are unchanged. Signed-zero Value equality and duplicate-preserving digests remain separate decisions. Asymmetric exhaustion continues until both EOF; no rows are sampled or skipped."
    },
    {
      "area": "Resource compatibility",
      "finding": "Both A and B full spools still run before comparison. Same 64/8/1 insert tiers,64KiB buffer,limits,per-row accounting,page cap,read snapshots,temp lifecycle and source projection. The previously restored SQLITE_FULL behavior is not bypassed. Report table fields and top-level schema unchanged; no public witness field reintroduced."
    },
    {
      "area": "Bounded examples",
      "finding": "example() remains unchanged and owns JSON Values or digest summaries before row borrow expires. First-three limit and16KiB body bound remain unchanged."
    }
  ],
  "new_controls_static_review": [
    {
      "name": "borrowed_cursor_text_matches_owned_conversion_and_row_storage",
      "scope": "Plain/Unicode/NUL/empty TEXT, malformed UTF8,NULL,INTEGER,REAL,BLOB; compares original owned String result/error Debug and Display/db_error, verifies successful pointer/length equals actual ValueRef text. This tests allocation mechanism and exact conversion, not runtime speed."
    },
